def lookup_cve(cve_id: str) -> Optional[VulnerabilityRecord]:
    return CVE_DATABASE.get(cve_id.upper())

def filter_by_severity(severity: str) -> List[VulnerabilityRecord]:
    return [v for v in CVE_DATABASE.values() if v.severity.upper() == severity.upper()]

def search_by_cwe(cwe_id: str) -> List[VulnerabilityRecord]:
    return [v for v in CVE_DATABASE.values() if cwe_id.upper() in v.cwe_id.upper()]
